package android.content;import java.io.*;import java.util.*;
public class Context {final File root;final Map<String,SharedPreferences> prefs=new HashMap<>();public Context(File f){root=f;f.mkdirs();}public File getFilesDir(){return root;}public SharedPreferences getSharedPreferences(String k,int m){return prefs.computeIfAbsent(k,x->new Memory());}static class Memory implements SharedPreferences{final Map<String,Object> data=new HashMap<>();public boolean contains(String k){return data.containsKey(k);}public int getInt(String k,int d){return data.containsKey(k)?(Integer)data.get(k):d;}public boolean getBoolean(String k,boolean d){return data.containsKey(k)?(Boolean)data.get(k):d;}public Editor edit(){return new Editor(){Map<String,Object> changes=new HashMap<>();public Editor putInt(String k,int v){changes.put(k,v);return this;}public Editor putBoolean(String k,boolean v){changes.put(k,v);return this;}public boolean commit(){data.putAll(changes);return true;}};}}}
